def getValueFromArray(arr, size, index):
    if index < 0 or index >= size:
        return -1  # अमान्य सूचकांक के लिए त्रुटि मान
    return arr[index]

def main():
    size = int(input())
    arr = list(map(int, input().split()))
    index = int(input())
    result = getValueFromArray(arr, size, index)
    return result

if __name__ == "__main__":
    print(main())

